{
  "understanding": "材料D中“我先把两份记录按同一时段排好，再请大家比较”表明，甲在这次小组讨论中主动承担了组织比较的角色，而不只是转交资料；这一判断只限于本次讨论，不推断甲的一贯能力，也不声称它提高了全组最终成绩。",
  "strength": {
    "quote": "这里的“我先”说明整理发生在邀请比较之前，“按同一时段”则交代整理依据，使组员能够对照相同条件下的记录；因此，甲的工作给后续讨论提供了可共同使用的起点。",
    "feedback": "这处把材料D中的先后动作和整理标准分开说明，让读者看到“主动组织”不是空泛评价：先整理、再邀请比较，并且按同一时段整理，因此组员有共同可比较的基础。这个具体推断值得保留。"
  },
  "focus": [],
  "overview": "这段论证已经形成一个有限而清楚的判断：甲在本次讨论中主动组织比较。材料D支持动作与顺序，材料E补充说明这种安排回应了比较中的具体困难，材料F则回应“只是执行既定任务”的质疑，并把结论限定在本次讨论。论证链条完整，不需要再额外增加问题。"
}

{
  "understanding": "作者认为图书馆延长晚间开放能显著提高大多数学生的学习成绩，因此学校应每天开放到凌晨。",
  "strength": {
    "quote": "材料A中三名受访者都说，延长开放让小组讨论更方便，他们不用在宿舍走廊里找地方。",
    "feedback": "这句把“更方便”落实成一个具体场景：不用在走廊里找地方。读者能看见变化发生在哪里，这比只说“学生受益”更有说服力，值得保留。"
  },
  "focus": [
    {
      "quote": "即使材料B没有记录任何考试成绩，也不妨碍我们从学生的积极感受推断成绩必然提高。",
      "feedback": "读到这里，我跟不上的是从“讨论更方便”到“成绩显著提高”这一步。材料A说的是三名受访者的感受，材料B又明确说没有成绩记录，中间还缺一个环节，能说明“方便”为什么会导致成绩提高。请你回到原段，指出材料A中哪一句能直接支撑“成绩提高”，或者把结论缩小到材料能支持的范围（例如只写“学习条件更方便”），并说明还缺什么证据。"
    }
  ],
  "overview": "核心判断清楚：延长开放→提高成绩→应每天开放到凌晨。材料A的具体场景写得可感，但“三名受访者”被概括成“多数学生”，又直接推到“成绩必然提高”，证据与结论之间还差一步。建议先处理这一处，再考虑其他。"
}

{
  "understanding": "作者想用材料C中学生在社团群主动发出图书馆讨论邀请，说明公共空间能增强学习自主性，并进一步推断增加图书馆座位会促使学生主动邀请、提高自主性。",
  "strength": {
    "quote": "邀请者没有等待老师安排，而是自行提出时间和活动，因此他正在主动组织学习。",
    "feedback": "这句把“主动邀请”落到“提出时间和活动”这一具体动作上，读者能看出主动性不是空泛评价，而是有C中的邀请内容作依据；“正在主动组织学习”这个有限判断也因此站得住，值得保留。"
  },
  "focus": [
    {
      "quote": "由此可见，只要学校增加图书馆的座位，学生就会主动邀请同伴学习，学习自主性自然得到提高。",
      "feedback": "这里从C的一条群聊邀请，直接推到“增加座位”会普遍引发主动邀请，材料C只有这一次邀请、没有座位条件或更多学生行为的记录，前文也没有说明“公共性质”通过哪一步促成选择；因此“只要……就……”把一次行为变成了必然结果。请你在原段把这一句收回到C能支持的有限结论，写清这条邀请最多说明什么、尚不能说明什么；若要保留增加座位的推断，需要补充能直接核对座位条件与邀请行为关系的材料。"
    }
  ],
  "overview": "整体观点清楚，前半段能用C中的邀请动作支持“主动组织学习”这一有限判断；主要疑问在结尾从一次邀请跳到增加座位的普遍效果，证据链不足。"
}

{
  "understanding": "作者主张图书馆延长晚间开放到凌晨能显著提高大多数学生的学习成绩，因此学校应每天开放到凌晨。",
  "strength": {
    "quote": "有人担心延长时间会增加工作人员的负担，我认为学生成绩改善带来的收益更大，值得学校投入。",
    "feedback": "这处让读者看到你预判了“工作人员负担”这一质疑，并用收益与投入作权衡，承认与回应的结构值得保留。它能否站住，取决于前面“成绩改善”是否有足够证据；保留这个回应框架，同时把前面的证据补实即可。"
  },
  "focus": [
    {
      "quote": "这说明多数学生都从延长开放中受益。",
      "feedback": "读到“材料A中三名受访者都说，延长开放让小组讨论更方便”，我能跟上这三位受访者的感受；但下一句“这说明多数学生都从延长开放中受益”，我跟不上——“多数”是从哪里来的？三名受访者能否代表多数学生，读者看不到选择方式或范围。请把这句话缩到材料能支持的范围（例如只写“这三位受访者表示……”），或者补一句说明这三人的来源或代表性，让“多数”有依据。"
    },
    {
      "quote": "即使材料B没有记录任何考试成绩，也不妨碍我们从学生的积极感受推断成绩必然提高。",
      "feedback": "读到“学生的积极感受”，我能理解你指的是小组讨论更方便；但“推断成绩必然提高”这一步读者跟不上，因为“讨论方便”是学习条件，“成绩提高”是学习结果，中间还缺一个说明。请在这句前或句中写清楚：为什么讨论方便能导致成绩提高？或者把结论缩小到材料能支持的程度（如“改善了小组讨论条件”），并说明成绩提高还需要哪类证据。"
    }
  ],
  "overview": "整体读下来，论点清楚，有理由链（时间增加→成绩提高）、材料A的具体引用，也有对工作人员负担的承认与回应。主要卡在证据与结论之间的跨度：材料只支持“讨论方便”和三名受访者的感受，却推出“多数学生”和“成绩必然提高”。建议先处理这两处范围与推断步骤。"
}

{
  "understanding": "作者认为延长图书馆晚间开放时间能显著提高大多数学生的学习成绩，因此学校应该每天开放到凌晨。",
  "strength": {
    "quote": "图书馆延长晚间开放时间能够显著提高大多数学生的学习成绩，因此学校应该每天开放到凌晨。",
    "feedback": "这个主题句把因果判断（延长开放→成绩提高）和规范结论（学校应该做）都明确摆出来了，读者一读就知道要跟着作者论证什么，值得保留。"
  },
  "focus": [
    {
      "quote": "即使材料B没有记录任何考试成绩，也不妨碍我们从学生的积极感受推断成绩必然提高。",
      "feedback": "读到这句，我能理解作者想正面处理“没有成绩数据”这个困难。但“积极感受”和“成绩必然提高”不是一回事——材料B明确说没有收集考试成绩，那么“成绩是否提高”就没有直接证据。用感受来补成绩数据的缺，这个推断不成立。请作者考虑：如果要支持“成绩提高”这个核心判断，需要什么类型的证据？如果手头确实没有，是否可以把结论缩小为材料能支持的判断，比如“学生更愿意使用图书馆”或“小组讨论更方便”？"
    },
    {
      "quote": "材料A中三名受访者都说，延长开放让小组讨论更方便，他们不用在宿舍走廊里找地方。这说明多数学生都从延长开放中受益。",
      "feedback": "三名受访者的说法能支持“有学生觉得讨论更方便”，但“多数学生”需要更多样本才能成立。而且材料A说的是“讨论方便”，和核心判断的“成绩提高”之间还缺一步：讨论方便如何导致成绩提高？请作者考虑：是要补充更多学生反馈来支持“多数”，还是要解释“讨论方便”与“成绩提高”之间的具体联系？"
    }
  ],
  "overview": "整体上，作者的主题句清晰，理由方向也容易跟上。主要疑问集中在证据与核心判断“成绩提高”之间的衔接：材料A只涉及“讨论方便”，材料B明确没有成绩数据，作者用“积极感受”来支撑“成绩必然提高”，这一步推断需要调整或补充。"
}

{
  "understanding": "作者主张延长图书馆晚间开放能显著提高大多数学生的学习成绩，因此学校应该每天开放到凌晨。",
  "strength": {
    "quote": "材料A中三名受访者都说，延长开放让小组讨论更方便，他们不用在宿舍走廊里找地方。",
    "feedback": "这句具体引了材料A，读者能清楚看到你手里是什么证据。“不用在宿舍走廊里找地方”这个细节也让“方便”有了可理解的画面，值得保留。"
  },
  "focus": [
    {
      "quote": "这说明多数学生都从延长开放中受益。",
      "feedback": "读到材料A里三人说“小组讨论更方便”，我能看出你指的是一种便利。但“三名受访者”怎么能说明“多数学生”？而且你后来说“从学生的积极感受推断成绩必然提高”——材料A里三人的“积极感受”是关于“小组讨论更方便”的，这和“成绩提高”之间，你能看到的具体环节是什么？材料B已经说了没有成绩记录。能不能先在这句里说清“受益”具体指什么，再把“多数”和“必然”收窄到这三人的说法能支持的范围？"
    }
  ],
  "overview": "整体能看出你想论证什么，材料A的引用也具体、忠实。主要疑问在从三名受访者的“方便”感受跳到“多数学生受益”和“成绩必然提高”这一步。"
}

{
  "understanding": "作者认为材料C中学生主动邀请去图书馆讨论，说明公共空间（图书馆）能增强学生的学习自主性，并据此主张增加图书馆座位就能提高学习自主性。",
  "strength": {
    "quote": "邀请者没有等待老师安排，而是自行提出时间和活动，因此他正在主动组织学习。",
    "feedback": "这一句从材料C的具体行为——主动发出邀请、提出“今晚八点”的时间和“一起去图书馆讨论”的活动——推出“主动组织学习”的有限判断，读者能跟上，因为材料C确实记录了一个没有老师分配的主动邀请。值得保留“自行提出时间和活动”这个具体描述，它让“主动”有了可核对的依据。"
  },
  "focus": [
    {
      "quote": "图书馆是学校的公共设施，正是这种公共性质促成了他的主动选择。",
      "feedback": "读到“邀请去图书馆”，我能理解邀请发生的地点；但读到“正是这种公共性质促成了他的主动选择”，我跟不上了。材料C只记录了一条邀请信息，没有说明邀请者为什么选图书馆，也没有提到“公共性质”起了什么作用。请你看看材料C里有没有线索能说明是图书馆的公共性（而不是别的因素，比如离得近、安静之类）促成了这个选择；如果没有，可以考虑把判断缩小到材料能支持的范围，比如只说邀请者选择了图书馆作为讨论地点，而不替他说出选择的原因。"
    },
    {
      "quote": "有人认为邀请也可能通过私人书信或聊天软件发出，与公共空间无关；但图书馆有很多书，这就足以回应这一质疑。",
      "feedback": "这个质疑的要点是“邀请可以通过别的渠道发出，所以不能从群聊邀请推出公共空间的作用”。作者回应“图书馆有很多书”——这说的是图书馆有什么，没有回答“邀请渠道与公共空间有什么关系”这个问题。而且材料C没有提到图书馆有书。请你按质疑者能接受的说法复述一遍质疑，再看自己的回应有没有回答同一个问题；如果材料C提供不了选择原因的线索，或许可以承认这个质疑成立，把判断缩小到“邀请指向图书馆，但不能确定公共空间起了作用”。"
    }
  ],
  "overview": "整体上段落有明确的判断和材料引用，前半段从材料C推出“主动组织学习”有依据；主要疑问在从“邀请去图书馆”跳到“公共性质促成选择”这一步，材料没有提供选择原因的线索。回应质疑那段也没有回答“邀请渠道”的问题。"
}
